{
  "Version": "2012-10-17",
  "Id": "key-policy-order-service",
  "Statement": [
    {
      "Sid": "Allow administration by SecurityAdmin",
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::123456789012:role/SecurityAdmin"
      },
      "Action": [
        "kms:DescribeKey",
        "kms:EnableKeyRotation",
        "kms:ListKeys",
        "kms:CreateAlias"
      ],
      "Resource": "*"
    },
    {
      "Sid": "Allow usage by order-service-role",
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::123456789012:role/order-service-role"
      },
      "Action": [
        "kms:Decrypt",
        "kms:GenerateDataKey"
      ],
      "Resource": "*"
    }
  ]
}

Separation rationale: By separating admin (who can delete/disable keys) from usage (who encrypts/decrypts data), we reduce the risk that a compromised application role could permanently lock or destroy the key, and it ensures dual control for critical actions.
